-- ── the post-migration assertion (the 0117 model, A7) ────────────────────
-- Made-up uuids. One valid base row (a live record with its e-way bill); each
-- shape merges an override over it (`jsonb_populate_record`) with a fresh id,
-- order and client. The accepted shapes are inserted and rolled back by a
-- sentinel, so a CHECK that refused everything fails the migration; each
-- refused shape runs in its own subtransaction and must be refused BY ITS
-- NAMED CONSTRAINT (CHECKs run in name order, guide §3: each probe violates
-- only its target, or its target is the first in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	o uuid;
	base jsonb;
	rec jsonb;
	refused_by text;
	message text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'seq', 1, 'status', 'live',
		'brand_document_type', 'invoice', 'brand_document_number', 'INV/26-27/0042', 'brand_document_date', '2026-10-30',
		'consignor_gstin', '29ABCDE1234F1Z5', 'consignor_snapshot', '{"v":1,"code":"ACME","name":"Acme"}'::jsonb,
		'declared_value_paise', 11800000, 'destination_state_code', '27', 'supply_type', 'inter',
		'threshold_paise', 5000000, 'threshold_rule', 'national', 'eway_required', true,
		'eway_status', 'recorded', 'eway_bill_number', '123456789012', 'eway_bill_date', '2026-10-30', 'eway_valid_until', '2026-11-01',
		'eway_exemption_reason', NULL, 'eway_exemption_note', NULL,
		'recorded_after_dispatch', false, 'dispatched_at', NULL, 'source', 'portal',
		'recorded_by', u, 'recorded_at', now(), 'ended_at', NULL, 'ended_by', NULL, 'end_reason', NULL,
		'created_at', now(), 'updated_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a recorded e-way bill', '{}'),
			('an e-way bill owed', '{"eway_status":"pending","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
			('below the threshold', '{"declared_value_paise":4200000,"eway_required":false,"eway_status":"not-required","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
			('exactly the threshold', '{"declared_value_paise":5000000,"eway_required":false,"eway_status":"not-required","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
			('exempt goods', '{"eway_status":"exempt","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null,"eway_exemption_reason":"exempt-goods"}'),
			('exempt, other with a note', '{"eway_status":"exempt","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null,"eway_exemption_reason":"other","eway_exemption_note":"Hand carried"}'),
			('a superseded version with a reason', '{"status":"superseded","seq":2,"ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"Amended","dispatched_at":"2026-10-30T00:00:00Z"}'),
			('a withdrawn version', '{"status":"withdrawn","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"Order cancelled"}'),
			('an intra-state record under a state override', '{"destination_state_code":"29","supply_type":"intra","threshold_paise":10000000,"threshold_rule":"state:29","declared_value_paise":8000000,"eway_required":false,"eway_status":"not-required","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
			('an unresolved destination', '{"destination_state_code":null,"supply_type":null}'),
			('a NULL state override (no bill required)', '{"supply_type":"intra","destination_state_code":"29","threshold_paise":null,"threshold_rule":"state:29","eway_required":false,"eway_status":"not-required","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
			('a web record after dispatch, version 99', '{"source":"web","seq":99,"recorded_after_dispatch":true,"dispatched_at":"2026-10-30T00:00:00Z"}'),
			('a challan', '{"brand_document_type":"challan"}'),
			('a bill of supply', '{"brand_document_type":"bill-of-supply"}')
		) AS s(name, override) LOOP
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid(), 'client_id', gen_random_uuid())
				|| replace(shape.override, '%U%', u::text)::jsonb;
			INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0118: an accepted record shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('status open', 'order_consignment_records_status_check', '{"status":"open","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"x"}'),
		('seq 100', 'order_consignment_records_seq_range', '{"seq":100}'),
		('seq 0', 'order_consignment_records_seq_range', '{"seq":0}'),
		('a handheld source', 'order_consignment_records_source_check', '{"source":"handheld"}'),
		('a debit note', 'order_consignment_records_brand_document_type_check', '{"brand_document_type":"debit-note"}'),
		('a 41-character document number', 'order_consignment_records_brand_document_number_length', '{"brand_document_number":"%LONG41%"}'),
		('an empty document number', 'order_consignment_records_brand_document_number_length', '{"brand_document_number":""}'),
		('a lower-case consignor GSTIN', 'order_consignment_records_consignor_gstin_shape', '{"consignor_gstin":"29abcde1234f1z5"}'),
		('a consignor snapshot v2', 'order_consignment_records_consignor_snapshot_shape', '{"consignor_snapshot":{"v":2}}'),
		('a consignor snapshot as an array', 'order_consignment_records_consignor_snapshot_shape', '{"consignor_snapshot":[1]}'),
		('a negative declared value', 'order_consignment_records_declared_value_range', '{"declared_value_paise":-1}'),
		('a declared value over 10^12', 'order_consignment_records_declared_value_range', '{"declared_value_paise":1000000000001}'),
		('an unknown supply type', 'order_consignment_records_supply_type_check', '{"supply_type":"cross"}'),
		('a destination without its supply type', 'order_consignment_records_destination_pairing', '{"supply_type":null}'),
		('a three-digit destination', 'order_consignment_records_destination_pairing', '{"destination_state_code":"270"}'),
		('a malformed threshold rule', 'order_consignment_records_threshold_rule_shape', '{"threshold_rule":"state:2"}'),
		('eway_required contradicting the value', 'order_consignment_records_eway_required_derived', '{"eway_required":false}'),
		('an unknown e-way status', 'order_consignment_records_eway_status_check', '{"eway_status":"generated","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
		('recorded without a number', 'order_consignment_records_eway_recorded_pairing', '{"eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
		('a number without its date', 'order_consignment_records_eway_recorded_pairing', '{"eway_bill_date":null}'),
		('an 11-digit number', 'order_consignment_records_eway_number_shape', '{"eway_bill_number":"12345678901"}'),
		('valid until before the e-way date', 'order_consignment_records_eway_dates', '{"eway_valid_until":"2026-10-29"}'),
		('an e-way date before the document date', 'order_consignment_records_eway_dates', '{"eway_bill_date":"2026-10-29"}'),
		('a recorded bill without its validity', 'order_consignment_records_eway_validity_required', '{"eway_valid_until":null}'),
		('other without a note', 'order_consignment_records_eway_exempt_pairing', '{"eway_status":"exempt","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null,"eway_exemption_reason":"other"}'),
		('an unknown exemption reason', 'order_consignment_records_eway_exempt_pairing', '{"eway_status":"exempt","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null,"eway_exemption_reason":"diplomatic"}'),
		('an exemption on a recorded bill', 'order_consignment_records_eway_exempt_pairing', '{"eway_exemption_reason":"customs"}'),
		('a note without a reason', 'order_consignment_records_eway_exempt_pairing', '{"eway_exemption_note":"x"}'),
		('a pending record under its threshold', 'order_consignment_records_eway_status_by_requirement', '{"declared_value_paise":4200000,"eway_required":false,"eway_status":"pending","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
		('a not-required record over its threshold', 'order_consignment_records_eway_status_by_requirement', '{"eway_status":"not-required","eway_bill_number":null,"eway_bill_date":null,"eway_valid_until":null}'),
		('a live record with an end reason', 'order_consignment_records_end_pairing', '{"end_reason":"x"}'),
		('a superseded record without its end', 'order_consignment_records_end_pairing', '{"status":"superseded"}'),
		('a superseded record without a reason', 'order_consignment_records_end_pairing', '{"status":"superseded","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%"}'),
		('a 201-character end reason', 'order_consignment_records_end_pairing', '{"status":"withdrawn","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"%LONG201%"}'),
		('NULL brand document date', 'not-null:brand_document_date', '{"brand_document_date":null}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid(), 'client_id', gen_random_uuid())
				|| replace(replace(replace(probe.override, '%U%', u::text), '%LONG41%', repeat('x', 41)), '%LONG201%', repeat('x', 201))::jsonb;
			INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				GET STACKED DIAGNOSTICS refused_by = COLUMN_NAME;
				refused_by := 'not-null:' || refused_by;
			WHEN SQLSTATE 'P0118' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0118: record probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- One live version per order; an e-way number live once per client.
	BEGIN
		o := gen_random_uuid();
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'client_id', u);
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'client_id', u, 'seq', 2, 'eway_bill_number', '999999999999');
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'two live versions landed';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'order_consignment_records_live_unique' THEN
				RAISE EXCEPTION 'migration 0118: a second live version was refused by % (expected order_consignment_records_live_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0118' THEN
			RAISE EXCEPTION 'migration 0118: two live versions of one order were accepted.';
	END;
	BEGIN
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid(), 'client_id', u);
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		-- Another client may hold the same number (uniqueness is per client).
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid(), 'client_id', gen_random_uuid());
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid(), 'client_id', u);
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'one e-way number live twice';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'order_consignment_records_client_eway_live_unique' THEN
				RAISE EXCEPTION 'migration 0118: a reused e-way number was refused by % (expected order_consignment_records_client_eway_live_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0118' THEN
			RAISE EXCEPTION 'migration 0118: one client''s e-way number was live on two orders.';
	END;
	-- The trigger: a number never changes; the ending columns and one stamp do.
	BEGIN
		o := gen_random_uuid();
		rec := base || jsonb_build_object('id', o, 'order_id', gen_random_uuid(), 'client_id', gen_random_uuid());
		INSERT INTO "order_consignment_records" SELECT (jsonb_populate_record(NULL::"order_consignment_records", rec)).*;
		BEGIN
			UPDATE "order_consignment_records" SET "brand_document_number" = 'INV-2' WHERE "id" = o;
			RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a number was rewritten';
		EXCEPTION
			WHEN SQLSTATE 'P0001' THEN
				GET STACKED DIAGNOSTICS message = MESSAGE_TEXT;
				IF message NOT LIKE 'order_consignment_records is immutable: only%' THEN
					RAISE EXCEPTION 'migration 0118: the number rewrite was refused by "%".', message;
				END IF;
			WHEN SQLSTATE 'P0118' THEN
				RAISE EXCEPTION 'migration 0118: the trigger let a document number be rewritten.';
		END;
		UPDATE "order_consignment_records" SET "dispatched_at" = now(), "updated_at" = now() WHERE "id" = o;
		BEGIN
			UPDATE "order_consignment_records" SET "dispatched_at" = now() + interval '1 day' WHERE "id" = o;
			RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a dispatch stamp was rewritten';
		EXCEPTION
			WHEN SQLSTATE 'P0001' THEN
				GET STACKED DIAGNOSTICS message = MESSAGE_TEXT;
				IF message <> 'order_consignment_records is immutable: dispatched_at is stamped once' THEN
					RAISE EXCEPTION 'migration 0118: the re-stamp was refused by "%".', message;
				END IF;
			WHEN SQLSTATE 'P0118' THEN
				RAISE EXCEPTION 'migration 0118: the trigger let dispatched_at be stamped twice.';
		END;
		UPDATE "order_consignment_records" SET "status" = 'superseded', "ended_at" = now(), "ended_by" = u, "end_reason" = 'Amended' WHERE "id" = o;
		-- An ended version is frozen: never revived, its ending never rewritten.
		BEGIN
			UPDATE "order_consignment_records" SET "status" = 'live', "ended_at" = NULL, "ended_by" = NULL, "end_reason" = NULL WHERE "id" = o;
			RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a version was revived';
		EXCEPTION
			WHEN SQLSTATE 'P0001' THEN
				GET STACKED DIAGNOSTICS message = MESSAGE_TEXT;
				IF message NOT LIKE 'order_consignment_records is immutable: an ended version%' THEN
					RAISE EXCEPTION 'migration 0118: the revival was refused by "%".', message;
				END IF;
			WHEN SQLSTATE 'P0118' THEN
				RAISE EXCEPTION 'migration 0118: the trigger let an ended version be revived.';
		END;
		BEGIN
			UPDATE "order_consignment_records" SET "end_reason" = 'Rewritten' WHERE "id" = o;
			RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'an ending was rewritten';
		EXCEPTION
			WHEN SQLSTATE 'P0001' THEN
				GET STACKED DIAGNOSTICS message = MESSAGE_TEXT;
				IF message NOT LIKE 'order_consignment_records is immutable: an ended version%' THEN
					RAISE EXCEPTION 'migration 0118: the ending rewrite was refused by "%".', message;
				END IF;
			WHEN SQLSTATE 'P0118' THEN
				RAISE EXCEPTION 'migration 0118: the trigger let an ending be rewritten.';
		END;
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the trigger probes';
	EXCEPTION
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	IF EXISTS (SELECT 1 FROM "order_consignment_records" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0118: a record probe row survived.';
	END IF;
END $$;
--> statement-breakpoint
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
BEGIN
	-- clients: each rule accepted, an unknown one refused.
	BEGIN
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned","consignment_document_rule")
		VALUES (gen_random_uuid(), t, 'P-B2B', 'Probe', 'active', false, 'b2b'),
		       (gen_random_uuid(), t, 'P-ALL', 'Probe', 'active', false, 'all'),
		       (gen_random_uuid(), t, 'P-HIGH', 'Probe', 'active', false, 'high-value');
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0118: an accepted client rule was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	refused_by := NULL;
	BEGIN
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned","consignment_document_rule")
		VALUES (gen_random_uuid(), t, 'P-NONE', 'Probe', 'active', false, 'none');
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'clients_consignment_document_rule_check' THEN
		RAISE EXCEPTION 'migration 0118: the rule "none" was refused by % (expected clients_consignment_document_rule_check).', coalesce(refused_by, 'nothing');
	END IF;
	-- shipments: an exception rides a handover only.
	BEGIN
		INSERT INTO "shipments" ("id","tenant_id","warehouse_id","order_id","client_id","status","kind","carrier_name","tracking_number","label_attachment_id","package_count","labelled_by","labelled_at","recorded_surface",
			"handover_id","handed_over_at","label_verified_at","label_verified_by","label_verify_method","compliance_exception")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'handed_over', 'client-label', 'Delhivery', 'AWB0118', gen_random_uuid(), 1, u, now(), 'portal',
			gen_random_uuid(), now(), now(), u, 'handover-scan', 'consignment-documents-missing');
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0118: a handed-over shipment with an exception was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	refused_by := NULL;
	BEGIN
		INSERT INTO "shipments" ("id","tenant_id","warehouse_id","order_id","client_id","status","kind","carrier_name","tracking_number","label_attachment_id","package_count","labelled_by","labelled_at","recorded_surface","compliance_exception")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'labelled', 'client-label', 'Delhivery', 'AWB0119', gen_random_uuid(), 1, u, now(), 'portal', 'eway-bill-required');
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'shipments_compliance_exception_check' THEN
		RAISE EXCEPTION 'migration 0118: an exception on a labelled shipment was refused by % (expected shipments_compliance_exception_check).', coalesce(refused_by, 'nothing');
	END IF;
	refused_by := NULL;
	BEGIN
		INSERT INTO "shipments" ("id","tenant_id","warehouse_id","order_id","client_id","status","kind","carrier_name","tracking_number","label_attachment_id","package_count","labelled_by","labelled_at","recorded_surface",
			"handover_id","handed_over_at","label_verified_at","label_verified_by","label_verify_method","compliance_exception")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'handed_over', 'client-label', 'Delhivery', 'AWB0120', gen_random_uuid(), 1, u, now(), 'portal',
			gen_random_uuid(), now(), now(), u, 'handover-scan', 'paperwork-missing');
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'shipments_compliance_exception_check' THEN
		RAISE EXCEPTION 'migration 0118: an unknown exception code was refused by % (expected shipments_compliance_exception_check).', coalesce(refused_by, 'nothing');
	END IF;
	-- vendor_returns: a declared value of 0 and of 10^12 is accepted.
	BEGIN
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","declared_value_paise")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'RTV-P119', 'draft', 'dispatch', '{}', '{}', u, 0),
		       (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'RTV-P120', 'draft', 'dispatch', '{}', '{}', u, 1000000000000);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0118: an accepted declared value was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	refused_by := NULL;
	BEGIN
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","declared_value_paise")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'RTV-P121', 'draft', 'dispatch', '{}', '{}', u, 1000000000001);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'vendor_returns_declared_value_range' THEN
		RAISE EXCEPTION 'migration 0118: a declared value over 10^12 was refused by % (expected vendor_returns_declared_value_range).', coalesce(refused_by, 'nothing');
	END IF;
	-- vendor_returns: a declared value is 0–10^12.
	refused_by := NULL;
	BEGIN
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","declared_value_paise")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'RTV-P118', 'draft', 'dispatch', '{}', '{}', u, -1);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'vendor_returns_declared_value_range' THEN
		RAISE EXCEPTION 'migration 0118: a negative declared value was refused by % (expected vendor_returns_declared_value_range).', coalesce(refused_by, 'nothing');
	END IF;
	-- mail: the documents-needed notice is a client template.
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
		VALUES (gen_random_uuid(), t, 'client-documents-needed', 'a@example.in', '{}', 'pending', now(), u, 'client-documents-needed:o1:a@example.in', 1);
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles","email_events")
		VALUES (gen_random_uuid(), t, u, 'Asha', 'asha@example.in', '{}', ARRAY['order.dispatched', 'consignment.documents-needed']);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0118: an accepted mail or contact shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0118' THEN
			NULL;
	END;
	refused_by := NULL;
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
		VALUES (gen_random_uuid(), t, 'client-documents-needed', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 1);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'email_messages_client_shape_check' THEN
		RAISE EXCEPTION 'migration 0118: a documents-needed row without a client was refused by % (expected email_messages_client_shape_check).', coalesce(refused_by, 'nothing');
	END IF;
	refused_by := NULL;
	BEGIN
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles","email_events")
		VALUES (gen_random_uuid(), t, u, 'Asha', 'asha2@example.in', '{}', ARRAY['consignment.documents-needed', 'consignment.documents-needed']);
		RAISE EXCEPTION USING ERRCODE = 'P0118', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0118' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'client_contacts_email_events_check' THEN
		RAISE EXCEPTION 'migration 0118: a duplicate documents-needed event was refused by % (expected client_contacts_email_events_check).', coalesce(refused_by, 'nothing');
	END IF;
	IF EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "shipments" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "vendor_returns" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_contacts" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0118: a probe row survived.';
	END IF;
END $$;
